package controller
import("errors";"net/http";"time";"github.com/gin-gonic/gin";"github.com/google/uuid";"github.com/onoja217/users-management-app/internal/audit";"github.com/onoja217/users-management-app/internal/httpx";"github.com/onoja217/users-management-app/internal/middleware";"github.com/onoja217/users-management-app/internal/service")
type PersonOnboardingController struct{service *service.PersonOnboardingService}
func NewPersonOnboardingController(s *service.PersonOnboardingService)*PersonOnboardingController{return &PersonOnboardingController{service:s}}
type PersonOnboardingRequest struct{Name string `json:"name" binding:"required,min=2,max=100"`;Email string `json:"email" binding:"required,email,max=255"`;Password string `json:"password" binding:"required,min=8,max=128"`;Role string `json:"role" binding:"required"`;AdmissionNumber string `json:"admission_number" binding:"omitempty,min=2,max=50"`;EnrollmentStatus string `json:"enrollment_status" binding:"omitempty,oneof=active inactive graduated withdrawn"`;StaffID string `json:"staff_id" binding:"omitempty,min=2,max=80"`;Phone string `json:"phone" binding:"omitempty,max=30"`;Gender string `json:"gender" binding:"omitempty,max=30"`;EmploymentDate *time.Time `json:"employment_date,omitempty"`;Department string `json:"department" binding:"omitempty,max=100"`;Designation string `json:"designation" binding:"omitempty,max=100"`;Subjects string `json:"subjects" binding:"omitempty,max=500"`;Classes string `json:"classes" binding:"omitempty,max=500"`;Status string `json:"status" binding:"omitempty,max=30"`;ParentIdentifier string `json:"parent_identifier" binding:"omitempty,max=100"`;Address string `json:"address" binding:"omitempty,max=255"`;Occupation string `json:"occupation" binding:"omitempty,max=100"`;StudentID uuid.UUID `json:"student_id"`;Relationship string `json:"relationship" binding:"omitempty,max=40"`;Primary bool `json:"primary"`}
func(ctrl *PersonOnboardingController)Create(c *gin.Context){schoolID,ok:=middleware.SchoolIDFromContext(c);if !ok{httpx.Error(c,403,"school_context_required","school context required");return};var req PersonOnboardingRequest;if e:=c.ShouldBindJSON(&req);e!=nil{httpx.Validation(c,httpx.ValidationErrors(e));return};result,e:=ctrl.service.Onboard(schoolID,service.PersonOnboardingRequest{Name:req.Name,Email:req.Email,Password:req.Password,Role:req.Role,AdmissionNumber:req.AdmissionNumber,EnrollmentStatus:req.EnrollmentStatus,StaffID:req.StaffID,Phone:req.Phone,Gender:req.Gender,EmploymentDate:req.EmploymentDate,Department:req.Department,Designation:req.Designation,Subjects:req.Subjects,Classes:req.Classes,Status:req.Status,ParentIdentifier:req.ParentIdentifier,Address:req.Address,Occupation:req.Occupation,StudentID:req.StudentID,Relationship:req.Relationship,Primary:req.Primary});if e!=nil{switch{case errors.Is(e,service.ErrOnboardingInvalidRole):httpx.Error(c,403,"invalid_school_user_role","school administrators cannot create platform or school administrator accounts");case errors.Is(e,service.ErrOnboardingDuplicateEmail):httpx.Error(c,409,"user_email_exists","email already exists");case errors.Is(e,service.ErrOnboardingDuplicateAdmission):httpx.Error(c,409,"duplicate_admission_number","admission number already exists");case errors.Is(e,service.ErrOnboardingStudentExists):httpx.Error(c,409,"student_already_exists","student profile already exists");case errors.Is(e,service.ErrOnboardingStudentNotFound):httpx.Error(c,404,"student_not_found","student not found in this school");case errors.Is(e,service.ErrOnboardingTeacherStaffIDRequired):httpx.Error(c,400,"teacher_staff_id_required","teacher staff ID is required");case errors.Is(e,service.ErrOnboardingTeacherProfileExists):httpx.Error(c,409,"teacher_profile_exists","teacher profile already exists");case errors.Is(e,service.ErrOnboardingParentProfileExists):httpx.Error(c,409,"parent_profile_exists","parent profile already exists");case errors.Is(e,service.ErrOnboardingGuardianInvalid):httpx.Error(c,400,"invalid_guardian_relationship","invalid guardian relationship");case errors.Is(e,service.ErrOnboardingGuardianLinkExists):httpx.Error(c,409,"guardian_link_exists","guardian is already linked to this student");default:httpx.Error(c,500,"onboarding_failed","school onboarding failed and was rolled back")};return};actor,_:=uuid.Parse(c.GetString("user_id"));_=audit.Record(ctrl.service.DB(),c,&actor,"school.onboarding.create","user",&result.User.ID,map[string]interface{}{"role":result.User.Role});c.JSON(http.StatusCreated,result)}
